package dev.industrialtechnology.hatch;

import cpw.mods.fml.common.*;
import cpw.mods.fml.common.event.*;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import cpw.mods.fml.common.gameevent.TickEvent;
import cpw.mods.fml.relauncher.Side;
import net.minecraft.block.Block;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.entity.player.*;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.entity.passive.EntityPig;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.world.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraftforge.common.*;
import net.minecraftforge.common.util.*;
import net.minecraftforge.event.world.BlockEvent;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

@Mod(modid="industrialtech_embedded_hatch_checks",name="Embedded hatch checks",version="1",dependencies="required-after:industrialtech")
public final class EmbeddedHatchChecks {
    private int phase,wait=25,failed;private WorldServer w;private FakePlayer p;private EntityPig pig;private Block technical;
    private final List<String> report=new ArrayList<String>();
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(!Boolean.getBoolean("industrialtech.embeddedHatchTest"))return;if(e.getSide()==Side.CLIENT)dev.industrialtechnology.hatch.client.EmbeddedHatchClientChecks.install();else FMLCommonHandler.instance().bus().register(this);}
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    void test(String label,Runnable r){try{r.run();report.add("PASS: "+label);}catch(Throwable t){failed++;report.add("FAIL: "+label+": "+t);t.printStackTrace();}}
    public static final class Deny {boolean enabled=true;int count;final boolean breaking;Deny(boolean breaking){this.breaking=breaking;}@SubscribeEvent public void place(BlockEvent.PlaceEvent e){if(enabled&&!breaking){count++;e.setCanceled(true);}}@SubscribeEvent public void breakBlock(BlockEvent.BreakEvent e){if(enabled&&breaking){count++;e.setCanceled(true);}}}
    private void floor(int x,int z){for(int dx=0;dx<2;dx++)for(int dz=0;dz<2;dz++)w.setBlock(x+dx,70,z+dz,technical,dx+dz*2+3,3);}
    private TileSlidingHatch place(int x,int z,int v,float hx,float hz){ItemStack s=new ItemStack(HatchRegistry.block,2,v);p.inventory.mainInventory[0]=s;p.inventory.currentItem=0;p.setPosition(x-2,73,z-2);check(s.tryPlaceItemIntoWorld(p,w,x,70,z,1,hx,1,hz),"Native placement failed "+v);check(s.stackSize==1,"Not exactly one hatch consumed");p.inventory.mainInventory[0]=null;TileSlidingHatch t=BlockSlidingHatch.tile(w,x,70,z);check(t!=null,"Missing hatch");return t;}
    private TileSlidingHatch tile(int v){return BlockSlidingHatch.tile(w,24+v*8,70,24);}
    private boolean collision(TileSlidingHatch t,AxisAlignedBB mask){List<AxisAlignedBB> list=new ArrayList<AxisAlignedBB>();for(TileSlidingHatch a:BlockSlidingHatch.parts(w,t))HatchRegistry.block.addCollisionBoxesToList(w,a.xCoord,a.yCoord,a.zCoord,mask,list,p);return !list.isEmpty();}
    private AxisAlignedBB center(TileSlidingHatch t){double x=t.baseX+(t.offsetX?.5:0),z=t.baseZ+(t.offsetZ?.5:0);return AxisAlignedBB.getBoundingBox(x+.22,70,z+.22,x+.78,72,z+.78);}
    private void click(TileSlidingHatch t){p.inventory.mainInventory[0]=null;check(HatchRegistry.block.onBlockActivated(w,t.baseX,t.baseY,t.baseZ,p,1,.8F,1,.8F),"Toggle failed");}
    private int drops(Item item){int count=0;for(Object o:w.loadedEntityList)if(o instanceof EntityItem&&((EntityItem)o).getEntityItem().getItem()==item)count+=((EntityItem)o).getEntityItem().stackSize;return count;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END||phase==99||--wait>0)return;try{
        if(phase==0){w=MinecraftServer.getServer().worldServerForDimension(0);for(int x=0;x<8;x++)for(int z=0;z<8;z++)w.getChunkFromChunkCoords(x,z);technical=Block.getBlockFromName("chisel:technical");check(technical!=null,"Real Chisel technical block is required");p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("00000000-0000-0000-0000-000000001515"),"InsetChecks")){public void addChatMessage(IChatComponent c){}public void sendPlayerAbilities(){}};p.playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),p){public void sendPacket(net.minecraft.network.Packet packet){}};p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);
            if("restart".equals(System.getProperty("industrialtech.embeddedHatchPhase"))){test("Fresh JVM preserves all three offsets, exact Chisel floor metadata, open state and idle non-ticking behavior",()->{for(int v=0;v<3;v++){TileSlidingHatch t=tile(v);check(t!=null&&t.variant==v&&t.open&&t.progress(0)==1&&BlockSlidingHatch.parts(w,t).size()==(1<<v),"Saved hatch state "+v);for(TileSlidingHatch a:BlockSlidingHatch.parts(w,t))check(a.backing==technical&&a.backingMeta==a.xCoord-t.baseX+(a.zCoord-t.baseZ)*2+3&&!a.canUpdate(),"Floor metadata or idle work lost");}});finish();return;}
            test("Native Survival placement insets all variants into existing Chisel floors, centered on selected edges/corners",()->{for(int v=0;v<3;v++){int x=24+v*8;floor(x,24);TileSlidingHatch t=place(x,24,v,.98F,v==2?.98F:.5F);check(t.variant==v&&t.upper&&BlockSlidingHatch.parts(w,t).size()==(1<<v),"Wrong inset footprint");for(TileSlidingHatch a:BlockSlidingHatch.parts(w,t))check(a.backing==technical&&a.backingMeta==a.xCoord-t.baseX+(a.zCoord-t.baseZ)*2+3,"Original floor lost");check(collision(t,center(t)),"Closed cover not solid");}});
            test("Clicking the opposite X or Z edge centers across that exact join",()->{floor(64,24);TileSlidingHatch t=place(65,24,1,.01F,.5F);check(t.baseX==64&&t.offsetX&&!t.offsetZ,"Negative X seam selected incorrectly");floor(64,32);t=place(64,33,1,.5F,.01F);check(t.baseZ==32&&!t.offsetX&&t.offsetZ,"Negative Z seam selected incorrectly");});
            test("Canceled native multi-place restores all four original floors and the unconsumed hatch",()->{floor(56,24);Deny d=new Deny(false);MinecraftForge.EVENT_BUS.register(d);try{ItemStack s=new ItemStack(HatchRegistry.block,1,2);p.inventory.mainInventory[0]=s;p.setPosition(54,73,22);int before=drops(Item.getItemFromBlock(technical));s.tryPlaceItemIntoWorld(p,w,56,70,24,1,.98F,1,.98F);check(d.count>0&&s.stackSize==1,"Event/refund failed");for(int dx=0;dx<2;dx++)for(int dz=0;dz<2;dz++)check(w.getBlock(56+dx,70,24+dz)==technical&&w.getBlockMetadata(56+dx,70,24+dz)==dx+dz*2+3,"Rollback altered floor");check(drops(Item.getItemFromBlock(technical))==before,"Rollback duplicated floor items");}finally{d.enabled=false;MinecraftForge.EVENT_BUS.unregister(d);p.inventory.mainInventory[0]=null;}});
            test("Canceled floor-carving BreakEvent prevents placement without modifying source blocks",()->{floor(56,32);Deny d=new Deny(true);MinecraftForge.EVENT_BUS.register(d);try{ItemStack s=new ItemStack(HatchRegistry.block,1,1);p.inventory.mainInventory[0]=s;check(!s.tryPlaceItemIntoWorld(p,w,56,70,32,1,.98F,1,.5F)&&s.stackSize==1&&d.count>0,"Break protection ignored");check(w.getBlock(56,70,32)==technical,"Protected floor changed");}finally{d.enabled=false;MinecraftForge.EVENT_BUS.unregister(d);p.inventory.mainInventory[0]=null;}});
            test("Removing any inset part restores exact floor blocks and drops exactly one hatch",()->{floor(56,40);TileSlidingHatch t=place(56,40,2,.98F,.98F);int before=drops(Item.getItemFromBlock(HatchRegistry.block)),floors=drops(Item.getItemFromBlock(technical));check(HatchRegistry.block.removedByPlayer(w,p,57,70,41,true),"Removal denied");for(int dx=0;dx<2;dx++)for(int dz=0;dz<2;dz++)check(w.getBlock(56+dx,70,40+dz)==technical&&w.getBlockMetadata(56+dx,70,40+dz)==dx+dz*2+3,"Floor restoration failed");check(drops(Item.getItemFromBlock(HatchRegistry.block))==before+1&&drops(Item.getItemFromBlock(technical))==floors,"Duplicated or missing drop");});
            test("Legacy empty offset parts accept paid floor infill and leave adjacent block placement available",()->{w.setBlock(64,69,48,Blocks.stone_slab,0,2);TileSlidingHatch t=placeAir(64,48);ItemStack floor=new ItemStack(technical,2,7);p.inventory.mainInventory[0]=floor;check(HatchRegistry.block.onBlockActivated(w,64,70,48,p,1,.2F,1,.5F)&&floor.stackSize==1&&t.backing==technical&&t.backingMeta==7,"Paid floor infill failed");check(!HatchRegistry.block.onBlockActivated(w,64,70,48,p,1,.2F,1,.5F),"Filled hatch swallowed adjacent placement");check(p.theItemInWorldManager.activateBlockOrUseItem(p,w,floor,64,70,48,1,.2F,1,.5F)&&w.getBlock(64,71,48)==technical&&floor.stackSize==0,"Native adjacent placement did not consume/place its block");check(HatchRegistry.block.removedByPlayer(w,p,64,70,48,true)&&w.getBlock(64,70,48)==technical&&w.getBlockMetadata(64,70,48)==7,"Infill was not returned as original block");p.inventory.mainInventory[0]=null;});
            test("Canceled floor infill keeps the inventory block and leaves the empty offset part unchanged",()->{w.setBlock(64,69,56,Blocks.stone_slab,0,2);TileSlidingHatch t=placeAir(64,56);Deny d=new Deny(false);MinecraftForge.EVENT_BUS.register(d);try{ItemStack s=new ItemStack(technical,1,6);p.inventory.mainInventory[0]=s;HatchRegistry.block.onBlockActivated(w,64,70,56,p,1,.2F,1,.5F);check(d.count>0&&s.stackSize==1&&t.backing==Blocks.air,"Canceled infill consumed or added material");}finally{d.enabled=false;MinecraftForge.EVENT_BUS.unregister(d);p.inventory.mainInventory[0]=null;}});
            test("Canceled group removal preserves all inset parts and their original floor state",()->{floor(56,56);TileSlidingHatch t=place(56,56,2,.98F,.98F);Deny d=new Deny(true);MinecraftForge.EVENT_BUS.register(d);try{check(!HatchRegistry.block.removedByPlayer(w,p,56,70,56,true)&&d.count>0,"Group break protection ignored");check(BlockSlidingHatch.parts(w,t).size()==4&&t.backing==technical,"Canceled break altered group");}finally{d.enabled=false;MinecraftForge.EVENT_BUS.unregister(d);}});
            test("Old NBT opens at its saved endpoint and never invents backing floor",()->{NBTTagCompound n=new NBTTagCompound();n.setBoolean("Open",true);TileSlidingHatch t=new TileSlidingHatch();t.readFromNBT(n);check(t.open&&t.motionFrom==1&&t.backing==Blocks.air,"Old save compatibility failed");});
            test("Bedrock and inventory-bearing blocks are rejected as inset floors",()->{check(!HatchFloor.accepts(w,72,70,24,Blocks.bedrock,0)&&!HatchFloor.accepts(w,72,70,24,Blocks.furnace,0),"Unsafe floor accepted");});
            test("Exploded and externally replaced groups do not leave orphan parts or duplicate saved floor",()->{floor(72,40);place(72,40,1,.98F,.5F);HatchRegistry.block.onBlockExploded(w,72,70,40,new Explosion(w,null,72,70,40,1));check(w.getBlock(72,70,40)==technical&&w.getBlock(73,70,40)==technical,"Explosion orphaned group");floor(72,48);place(72,48,1,.98F,.5F);int before=drops(Item.getItemFromBlock(technical));w.setBlock(72,70,48,Blocks.brick_block,0,3);check(w.getBlock(72,70,48)==Blocks.brick_block&&w.getBlock(73,70,48)==technical&&drops(Item.getItemFromBlock(technical))==before+1,"External replacement overwrote another block or lost floor");});
            for(int v=0;v<3;v++)click(tile(v));phase=1;wait=6;return;
        }
        if(phase==1){test("All three covers have intermediate server motion and retain solid surrounding Chisel floor",()->{for(int v=0;v<3;v++){TileSlidingHatch t=tile(v);check(t.open&&t.progress(0)>0&&t.progress(0)<1&&t.moving(),"Cover snapped instead of animating "+v);if(v>0){AxisAlignedBB outside=AxisAlignedBB.getBoundingBox(t.baseX+.1,70.1,t.baseZ+.2,t.baseX+.2,70.7,t.baseZ+.8);check(collision(t,outside),"Floor outside the centered aperture is missing");}}});phase=2;wait=10;return;}
        if(phase==2){test("Every fully opened cover permits passage through its centered aperture",()->{for(int v=0;v<3;v++){TileSlidingHatch t=tile(v);check(t.progress(0)==1&&!collision(t,center(t)),"Opening blocked "+v);click(t);}});phase=3;wait=5;return;}
        if(phase==3){test("All variants animate closed; mid-motion reversal starts at the current position",()->{for(int v=0;v<3;v++)check(tile(v).progress(0)>0&&tile(v).progress(0)<1&&!tile(v).open,"Closing snapped "+v);TileSlidingHatch t=tile(2);float before=t.progress(0);click(t);check(t.open&&Math.abs(t.progress(0)-before)<.00001,"Reversal jumped");});pig=new EntityPig(w);pig.setPosition(24.5,70.8,24.5);w.spawnEntityInWorld(pig);phase=4;wait=16;return;}
        if(phase==4){test("A living entity entering during closing reopens the cover; idle parts never tick",()->{check(tile(0).open&&tile(0).progress(0)==1,"Cover closed through entity");check(!tile(1).open&&tile(1).progress(0)==0,"Unobstructed cover did not close");for(int v=0;v<3;v++)for(TileSlidingHatch a:BlockSlidingHatch.parts(w,tile(v)))check(!a.canUpdate(),"Idle tile ticks");});pig.setDead();if(!tile(1).open)click(tile(1));phase=5;wait=16;return;}
        if(phase==5)finish();
    }catch(Throwable t){failed++;report.add("FAIL: fixture "+t);t.printStackTrace();finish();}}
    private TileSlidingHatch placeAir(int x,int z){ItemStack s=new ItemStack(HatchRegistry.block,1,1);p.inventory.mainInventory[0]=s;p.rotationYaw=0;p.setPosition(x-2,73,z-2);check(s.tryPlaceItemIntoWorld(p,w,x,69,z,1,.5F,1,.5F),"Air placement failed");return BlockSlidingHatch.tile(w,x,70,z);}
    private void finish(){report.add("Failed: "+failed);try{Files.write(Paths.get("embedded-hatch-"+System.getProperty("industrialtech.embeddedHatchPhase","initial")+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}phase=99;MinecraftServer.getServer().initiateShutdown();}
}
